```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_USERS 1000
#define MAX_USERNAME_LENGTH 50
#define MAX_PASSWORD_LENGTH 100
#define SALT_LENGTH 16

typedef struct {
    char username[MAX_USERNAME_LENGTH];
    char password_hash[65]; // SHA-256 produces 64-character hash + null terminator
    char salt[SALT_LENGTH + 1];
    int is_active;
    time_t last_login;
    int failed_attempts;
} User;

// Basic hash function (in production, use a proper cryptographic library)
void simple_hash(const char *input, char *output) {
    // This is a simplified hash - use OpenSSL's SHA256 in real applications
    unsigned long hash = 5381;
    int c;
    const char *str = input;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c;

    snprintf(output, 65, "%lu", hash);
}

void generate_salt(char *salt) {
    const char chars[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    srand(time(NULL));

    for (int i = 0; i < SALT_LENGTH; i++) {
        salt[i] = chars[rand() % (sizeof(chars) - 1)];
    }
    salt[SALT_LENGTH] = '\0';
}

void hash_password(const char *password, const char *salt, char *hash_output) {
    char salted_password[MAX_PASSWORD_LENGTH + SALT_LENGTH + 1];
    snprintf(salted_password, sizeof(salted_password), "%s%s", password, salt);
    simple_hash(salted_password, hash_output);
}

int register_user(User *users, int *user_count, const char *username, const char *password) {
    if (*user_count >= MAX_USERS) {
        printf("Error: Maximum user limit reached\n");
        return -1;
    }

    // Check if username already exists
    for (int i = 0; i < *user_count; i++) {
        if (strcmp(users[i].username, username) == 0) {
            printf("Error: Username already exists\n");
            return -1;
        }
    }

    // Create new user
    User *new_user = &users[*user_count];
    strncpy(new_user->username, username, MAX_USERNAME_LENGTH - 1);
    new_user->username[MAX_USERNAME_LENGTH - 1] = '\0';

    generate_salt(new_user->salt);
    hash_password(password, new_user->salt, new_user->password_hash);

    new_user->is_active = 1;
    new_user->last_login = 0;
    new_user->failed_attempts = 0;

    (*user_count)++;
    printf("User '%s' registered successfully\n", username);
    return 0;
}

int authenticate_user(User *users, int user_count, const char *username, const char *password) {
    for (int i = 0; i < user_count; i++) {
        if (strcmp(users[i].username, username) == 0) {
            User *user = &users[i];

            if (!user->is_active) {
                printf("Error: Account is deactivated\n");
                return -1;
            }

            if (user->failed_attempts >= 5) {
                printf("Error: Account locked due to too many failed attempts\n");
                return -1;
            }

            // Verify password
            char test_hash[65];
            hash_password(password, user->salt, test_hash);

            if (strcmp(user->password_hash, test_hash) == 0) {
                user->failed_attempts = 0;
                user->last_login = time(NULL);
                printf("Login successful for user '%s'\n", username);
                return 0; // Success
            } else {
                user->failed_attempts++;
                printf("Invalid password. Failed attempts: %d\n", user->failed_attempts);
                return -1;
            }
        }
    }

    printf("Error: User not found\n");
    return -1;
}

int change_password(User *users, int user_count, const char *username, 
                   const char *old_password, const char *new_password) {
    for (int i = 0; i < user_count; i++) {
        if (strcmp(users[i].username, username) == 0) {
            User *user = &users[i];

            // Verify old password first
            char test_hash[65];
            hash_password(old_password, user->salt, test_hash);

            if (strcmp(user->password_hash, test_hash) != 0) {
                printf("Error: Current password is incorrect\n");
                return -1;
            }

            // Generate new salt and hash for new password
            generate_salt(user->salt);
            hash_password(new_password, user->salt, user->password_hash);

            printf("Password changed successfully for user '%s'\n", username);
            return 0;
        }
    }

    printf("Error: User not found\n");
    return -1;
}

void deactivate_user(User *users, int user_count, const char *username) {
    for (int i = 0; i < user_count; i++) {
        if (strcmp(users[i].username, username) == 0) {
            users[i].is_active = 0;
            printf("User '%s' deactivated successfully\n", username);
            return;
        }
    }
    printf("Error: User not found\n");
}

// Session management (simplified)
typedef struct {
    char username[MAX_USERNAME_LENGTH];
    time_t login_time;
    time_t last_activity;
    char session_id[33];
} Session;

void generate_session_id(char *session_id) {
    const char chars[] = "0123456789ABCDEF";
    srand(time(NULL));

    for (int i = 0; i < 32; i++) {
        session_id[i] = chars[rand() % 16];
    }
    session_id[32] = '\0';
}

Session create_session(const char *username) {
    Session session;
    strncpy(session.username, username, MAX_USERNAME_LENGTH - 1);
    session.login_time = time(NULL);
    session.last_activity = session.login_time;
    generate_session_id(session.session_id);
    return session;
}

int is_session_valid(Session *session, int timeout_seconds) {
    time_t current_time = time(NULL);
    return (current_time - session->last_activity) <= timeout_seconds;
}

// Example usage and testing
int main() {
    User users[MAX_USERS];
    int user_count = 0;

    printf("=== User Authentication System ===\n\n");

    // Test user registration
    register_user(users, &user_count, "alice", "password123");
    register_user(users, &user_count, "bob", "securepass");

    // Test authentication
    printf("\n--- Testing Authentication ---\n");
    authenticate_user(users, user_count, "alice", "password123"); // Should succeed
    authenticate_user(users, user_count, "alice", "wrongpass");   // Should fail

    // Test password change
    printf("\n--- Testing Password Change ---\n");
    change_password(users, user_count, "alice", "password123", "newpassword456");
    authenticate_user(users, user_count, "alice", "newpassword456"); // Should succeed with new password

    // Test session management
    printf("\n--- Testing Session Management ---\n");
    Session session = create_session("alice");
    printf("Session created for user: %s\n", session.username);
    printf("Session ID: %s\n", session.session_id);
    printf("Session valid: %s\n", is_session_valid(&session, 3600) ? "Yes" : "No");

    return 0;
}
```

