        });

        // Handle form submission
        document.getElementById('userInputForm').addEventListener('submit', function(e) {
            e.preventDefault();

            const name = document.getElementById('name').value;
            const email = document.getElementById('email').value;
            const message = document.getElementById('message').value;

            if (name && email && message) {
                logUserInput(name, email, message);
                document.getElementById('userInputForm').reset();
                showMessage('Input logged successfully!', 'success');
                loadLogs(); // Refresh the log display
            } else {
                showMessage('Please fill in all fields.', 'error');
            }
        });

        // Function to log user input
        function logUserInput(name, email, message) {
            const logEntry = {
                timestamp: new Date().toISOString(),
                name: name,
                email: email,
                message: message
            };

            // Get existing logs or initialize empty array
            let logs = JSON.parse(localStorage.getItem('userInputLogs') || '[]');

            // Add new log entry
            logs.push(logEntry);

            // Save back to localStorage
            localStorage.setItem('userInputLogs', JSON.stringify(logs));
        }

        // Function to load and display logs
        function loadLogs() {
            const logs = JSON.parse(localStorage.getItem('userInputLogs') || '[]');
            const logContainer = document.getElementById('logEntries');

            if (logs.length === 0) {
                logContainer.innerHTML = '<p>No log entries found.</p>';
                return;
            }

            // Sort logs by timestamp (newest first)
            logs.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

            let html = '';
            logs.forEach(log => {
                const date = new Date(log.timestamp).toLocaleString();
                html += `
                    <div class="log-entry">
                        <div class="timestamp">${date}</div>
                        <div><strong>Name:</strong> ${log.name}</div>
                        <div><strong>Email:</strong> ${log.email}</div>
                        <div><strong>Message:</strong> ${log.message}</div>
                    </div>
                `;
            });

            logContainer.innerHTML = html;
        }

        // Function to clear all logs
        function clearLogs() {
            if (confirm('Are you sure you want to clear all logs?')) {
                localStorage.removeItem('userInputLogs');
                loadLogs();
                showMessage('All logs have been cleared.', 'success');
            }
        }

        // Function to show messages
        function showMessage(message, type) {
            const messageArea = document.getElementById('messageArea');
            messageArea.innerHTML = `<div class="${type}-message">${message}</div>`;

            // Clear message after 3 seconds
            setTimeout(() => {
                messageArea.innerHTML = '';
            }, 3000);
        }

        // Optional: Export logs as plain text file
        function exportLogs() {
            const logs = JSON.parse(localStorage.getItem('userInputLogs') || '[]');
            if (logs.length === 0) {
                showMessage('No logs to export.', 'error');
                return;
            }

            let textContent = 'User Input Logs\n';
            textContent += '================\n\n';

            logs.forEach(log => {
                const date = new Date(log.timestamp).toLocaleString();
                textContent += `Timestamp: ${date}\n`;
                textContent += `Name: ${log.name}\n`;
                textContent += `Email: ${log.email}\n`;
                textContent += `Message: ${log.message}\n`;
                textContent += '----------------\n\n';
            });

            const blob = new Blob([textContent], { type: 'text/plain' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = 'user_input_logs.txt';
            a.click();
            URL.revokeObjectURL(url);

            showMessage('Logs exported successfully!', 'success');
        }

        // Add export button functionality (optional)
        document.addEventListener('DOMContentLoaded', function() {
            const exportButton = document.createElement('button');
            exportButton.textContent = 'Export Logs';
            exportButton.onclick = exportLogs;
            exportButton.style.width = 'auto';
            exportButton.style.marginLeft = '10px';
            exportButton.style.backgroundColor = '#28a745';

            const clearButton = document.querySelector('button[onclick="clearLogs()"]');
            clearButton.parentNode.insertBefore(exportButton, clearButton.nextSibling);
        });
    </script>
</body>
</html>
