// JavaScript utility to disable browser console security warnings
(function() {
    'use strict';

    // Store original console methods
    const originalConsole = {
        warn: console.warn,
        error: console.error,
        info: console.info,
        log: console.log
    };

    // List of common security warning patterns to filter
    const securityWarningPatterns = [
        /Mixed Content/i,
        /Content Security Policy/i,
        /CORS/i,
        /Cross-Origin/i,
        /Secure Context/i,
        /HTTPS/i,
        /Certificate/i,
        /Security/i,
        /Warning.*security/i,
        /Deprecation.*security/i,
        /Blocked.*origin/i,
        /Violation.*policy/i
    ];

    // Function to check if a message contains security warnings
    function isSecurityWarning(message) {
        if (typeof message !== 'string') {
            message = String(message);
        }

        return securityWarningPatterns.some(pattern => 
            pattern.test(message)
        );
    }

    // Override console methods to filter security warnings
    console.warn = function(...args) {
        if (!isSecurityWarning(args[0])) {
            originalConsole.warn.apply(console, args);
        }
    };

    console.error = function(...args) {
        if (!isSecurityWarning(args[0])) {
            originalConsole.error.apply(console, args);
        }
    };

    // Optional: Override info and log to catch any security messages there too
    console.info = function(...args) {
        if (!isSecurityWarning(args[0])) {
            originalConsole.info.apply(console, args);
        }
    };

    console.log = function(...args) {
        if (!isSecurityWarning(args[0])) {
            originalConsole.log.apply(console, args);
        }
    };

    // Additional utility to completely suppress all warnings (more aggressive approach)
    function suppressAllWarnings() {
        console.warn = function() {};
        console.error = function() {};
    }

    // Function to restore original console methods
    function restoreConsole() {
        console.warn = originalConsole.warn;
        console.error = originalConsole.error;
        console.info = originalConsole.info;
        console.log = originalConsole.log;
    }

    // Browser-specific security warning suppression
    function disableBrowserSpecificWarnings() {
        // Disable CSP violations reporting
        if (window.SecurityPolicyViolationEvent) {
            window.addEventListener('securitypolicyviolation', function(e) {
                e.preventDefault();
                e.stopPropagation();
            }, true);
        }

        // Attempt to disable mixed content warnings
        if (window.chrome && window.chrome.webstore) {
            // Chrome specific - this is limited due to browser security
            try {
                // This won't actually disable mixed content but can help with console spam
                const originalFetch = window.fetch;
                if (originalFetch) {
                    window.fetch = function(...args) {
                        return originalFetch.apply(this, args).catch(error => {
                            // Suppress mixed content fetch errors in console
                            if (error && error.message && error.message.includes('mixed-content')) {
                                return Promise.reject(new Error('Request blocked'));
                            }
                            return Promise.reject(error);
                        });
                    };
                }
            } catch (e) {
                // Silently fail
            }
        }
    }

    // Configuration options
    const config = {
        filterSecurityWarnings: true,
        suppressAllWarnings: false,
        disableBrowserWarnings: true,
        verbose: false
    };

    // Initialize based on configuration
    function init(options = {}) {
        Object.assign(config, options);

        if (config.suppressAllWarnings) {
            suppressAllWarnings();
        } else if (config.filterSecurityWarnings) {
            // Already set up by default
        }

        if (config.disableBrowserWarnings) {
            disableBrowserSpecificWarnings();
        }

        if (config.verbose) {
            console.log('Security warning filter initialized');
        }
    }

    // Expose public API
    window.ConsoleSecurityFilter = {
        init,
        restoreConsole,
        suppressAllWarnings,
        isSecurityWarning,
        config
    };

    // Auto-initialize with default settings
    init();

})();

