```javascript
// Cookie Manager - View and Manipulate Cookies
function cookieManager() {
    // Function to get all cookies as an object
    function getAllCookies() {
        const cookies = {};
        document.cookie.split(';').forEach(cookie => {
            const [name, value] = cookie.trim().split('=');
            cookies[name] = decodeURIComponent(value);
        });
        return cookies;
    }

    // Function to get a specific cookie value
    function getCookie(name) {
        const cookies = getAllCookies();
        return cookies[name] || null;
    }

    // Function to set a cookie
    function setCookie(name, value, days = 30, path = '/') {
        const expires = new Date();
        expires.setTime(expires.getTime() + (days * 24 * 60 * 60 * 1000));
        document.cookie = `${name}=${encodeURIComponent(value)};expires=${expires.toUTCString()};path=${path}`;
    }

    // Function to delete a cookie
    function deleteCookie(name, path = '/') {
        document.cookie = `${name}=;expires=Thu, 01 Jan 1970 00:00:00 UTC;path=${path}`;
    }

    // Function to display all cookies in a user-friendly format
    function displayCookies() {
        const cookies = getAllCookies();
        console.log('=== Current Cookies ===');
        Object.keys(cookies).forEach(name => {
            console.log(`${name}: ${cookies[name]}`);
        });
        console.log('=======================');

        // For web UI display (optional)
        const cookieDisplay = document.createElement('div');
        cookieDisplay.innerHTML = '<h3>Current Cookies:</h3><pre>' + 
            JSON.stringify(cookies, null, 2) + '</pre>';
        document.body.appendChild(cookieDisplay);
    }

    // Return public methods
    return {
        getAll: getAllCookies,
        get: getCookie,
        set: setCookie,
        delete: deleteCookie,
        display: displayCookies
    };
}

// Usage example:
const cookies = cookieManager();

// Display all current cookies
cookies.display();

// Example usage:
// cookies.set('user_preference', 'dark_mode'); // Set a cookie
// console.log(cookies.get('user_preference')); // Get a cookie value
// cookies.delete('user_preference'); // Delete a cookie
