class NoteServer {
    constructor() {
        this.notes = new Map();
        this.connections = new Set();
    }

    handleConnection(ws) {
        this.connections.add(ws);

        ws.on('message', (data) => {
            const update = JSON.parse(data);
            this.processUpdate(update, ws);
        });

        ws.on('close', () => this.connections.delete(ws));
    }

    processUpdate(update, sourceWs) {
        const existingNote = this.notes.get(update.id);

        if (existingNote && existingNote.version >= update.version) {
            // Conflict detected
            const resolved = ConflictResolver.resolve(existingNote, update);
            this.notes.set(update.id, resolved);
        } else {
            this.notes.set(update.id, update);
        }

        // Broadcast to all connected clients except sender
        this.broadcastUpdate(update, sourceWs);
    }

    broadcastUpdate(update, excludeWs) {
        const message = JSON.stringify(update);
        this.connections.forEach(ws => {
            if (ws !== excludeWs && ws.readyState === WebSocket.OPEN) {
                ws.send(message);
            }
        });
    }
}

