```javascript
// Discount Code Generator and Manager
class DiscountManager {
    constructor() {
        this.discountCodes = new Map();
        this.userGroups = new Map();
    }

    // Generate a random discount code
    generateDiscountCode(length = 8) {
        const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
        let code = '';
        for (let i = 0; i < length; i++) {
            code += chars.charAt(Math.floor(Math.random() * chars.length));
        }
        return code;
    }

    // Create a new discount with specified parameters
    createDiscount(discountData) {
        const {
            name,
            discountType, // 'percentage' or 'fixed'
            value,
            minPurchaseAmount = 0,
            maxUses = null,
            validFrom = new Date(),
            validUntil = null,
            applicableProducts = null, // Array of product IDs or null for all products
            userGroups = [] // Array of user group IDs that can use this discount
        } = discountData;

        const code = this.generateDiscountCode();
        const discount = {
            code,
            name,
            discountType,
            value,
            minPurchaseAmount,
            maxUses,
            currentUses: 0,
            validFrom: new Date(validFrom),
            validUntil: validUntil ? new Date(validUntil) : null,
            applicableProducts,
            userGroups,
            isActive: true
        };

        this.discountCodes.set(code, discount);
        return discount;
    }

    // Check if a discount code is valid for a specific user and cart
    validateDiscount(code, userId, cartItems, totalAmount) {
        const discount = this.discountCodes.get(code);

        if (!discount || !discount.isActive) {
            return { valid: false, error: 'Invalid discount code' };
        }

        // Check validity dates
        const now = new Date();
        if (now < discount.validFrom) {
            return { valid: false, error: 'Discount code not yet active' };
        }
        if (discount.validUntil && now > discount.validUntil) {
            return { valid: false, error: 'Discount code has expired' };
        }

        // Check usage limits
        if (discount.maxUses && discount.currentUses >= discount.maxUses) {
            return { valid: false, error: 'Discount code usage limit reached' };
        }

        // Check minimum purchase amount
        if (totalAmount < discount.minPurchaseAmount) {
            return { 
                valid: false, 
                error: `Minimum purchase amount of $${discount.minPurchaseAmount} required` 
            };
        }

        // Check user groups
        if (discount.userGroups.length > 0) {
            const userGroup = this.getUserGroup(userId);
            if (!discount.userGroups.includes(userGroup)) {
                return { valid: false, error: 'Discount code not available for your user group' };
            }
        }

        // Check applicable products
        if (discount.applicableProducts) {
            const hasApplicableProduct = cartItems.some(item => 
                discount.applicableProducts.includes(item.productId)
            );
            if (!hasApplicableProduct) {
                return { valid: false, error: 'Discount code not applicable to cart items' };
            }
        }

        return { valid: true, discount };
    }

    // Apply discount to cart total
    applyDiscount(cartTotal, discount) {
        if (discount.discountType === 'percentage') {
            return cartTotal * (1 - discount.value / 100);
        } else if (discount.discountType === 'fixed') {
            return Math.max(0, cartTotal - discount.value);
        }
        return cartTotal;
    }

    // Get available discount codes for a user group
    getAvailableDiscounts(userGroup) {
        const now = new Date();
        return Array.from(this.discountCodes.values()).filter(discount => {
            if (!discount.isActive) return false;
            if (now < discount.validFrom) return false;
            if (discount.validUntil && now > discount.validUntil) return false;
            if (discount.userGroups.length > 0 && !discount.userGroups.includes(userGroup)) return false;
            if (discount.maxUses && discount.currentUses >= discount.maxUses) return false;
            return true;
        });
    }

    // Display discount codes to specific user groups
    displayDiscountsToUserGroup(userGroup, containerElement) {
        const availableDiscounts = this.getAvailableDiscounts(userGroup);

        if (availableDiscounts.length === 0) {
            containerElement.innerHTML = '<p>No discounts available for your group at this time.</p>';
            return;
        }

        const discountsHTML = availableDiscounts.map(discount => `
            <div class="discount-card">
                <h3>${discount.name}</h3>
                <p class="discount-code">Code: <strong>${discount.code}</strong></p>
                <p class="discount-value">
                    ${discount.discountType === 'percentage' ? 
                      `${discount.value}% OFF` : 
                      `$${discount.value} OFF`}
                </p>
                ${discount.minPurchaseAmount > 0 ? 
                  `<p>Min. purchase: $${discount.minPurchaseAmount}</p>` : ''}
                ${discount.validUntil ? 
                  `<p>Valid until: ${discount.validUntil.toLocaleDateString()}</p>` : ''}
            </div>
        `).join('');

        containerElement.innerHTML = discountsHTML;
    }

    // User group management
    addUserGroup(groupId, groupName) {
        this.userGroups.set(groupId, {
            id: groupId,
            name: groupName,
            users: new Set()
        });
    }

    addUserToGroup(userId, groupId) {
        const group = this.userGroups.get(groupId);
        if (group) {
            group.users.add(userId);
        }
    }

    getUserGroup(userId) {
        for (const [groupId, group] of this.userGroups) {
            if (group.users.has(userId)) {
                return groupId;
            }
        }
        return 'default'; // Default group for users without specific group
    }
}

