I'll help you create a PHP script to log user login attempts and store the data in a flat file. Here's a complete solution:

```php
<?php
class LoginLogger {
    private $logFile;
    private $maxFileSize; // in bytes
    private $backupCount;

    public function __construct($logFile = 'login_attempts.log', $maxFileSize = 10485760, $backupCount = 5) {
        $this->logFile = $logFile;
        $this->maxFileSize = $maxFileSize; // 10MB default
        $this->backupCount = $backupCount;

        // Create log file if it doesn't exist
        if (!file_exists($this->logFile)) {
            touch($this->logFile);
            chmod($this->logFile, 0644);
        }
    }

    public function logAttempt($username, $ipAddress, $status, $userAgent = '', $additionalInfo = '') {
        // Validate inputs
        if (empty($username) || empty($ipAddress) || empty($status)) {
            throw new InvalidArgumentException("Username, IP address, and status are required");
        }

        // Sanitize inputs
        $username = filter_var($username, FILTER_SANITIZE_STRING);
        $ipAddress = filter_var($ipAddress, FILTER_VALIDATE_IP) ? $ipAddress : 'Invalid IP';
        $status = in_array(strtolower($status), ['success', 'failed', 'locked']) ? strtolower($status) : 'unknown';
        $userAgent = filter_var($userAgent, FILTER_SANITIZE_STRING);
        $additionalInfo = filter_var($additionalInfo, FILTER_SANITIZE_STRING);

        // Create log entry
        $timestamp = date('Y-m-d H:i:s');
        $logEntry = json_encode([
            'timestamp' => $timestamp,
            'username' => $username,
            'ip_address' => $ipAddress,
            'status' => $status,
            'user_agent' => $userAgent,
            'additional_info' => $additionalInfo
        ]);

        // Rotate log file if it's too large
        $this->rotateLogIfNeeded();

        // Write to log file
        if (file_put_contents($this->logFile, $logEntry . PHP_EOL, FILE_APPEND | LOCK_EX)) {
            return true;
        } else {
            throw new Exception("Failed to write to log file");
        }
    }

    private function rotateLogIfNeeded() {
        if (file_exists($this->logFile) && filesize($this->logFile) >= $this->maxFileSize) {
            // Rotate existing logs
            for ($i = $this->backupCount - 1; $i >= 0; $i--) {
                $oldFile = $this->logFile . '.' . $i;
                $newFile = $this->logFile . '.' . ($i + 1);

                if (file_exists($oldFile)) {
                    if ($i == $this->backupCount - 1) {
                        unlink($oldFile); // Remove oldest backup
                    } else {
                        rename($oldFile, $newFile);
                    }
                }
            }

            // Rotate current log
            rename($this->logFile, $this->logFile . '.0');
            touch($this->logFile);
            chmod($this->logFile, 0644);
        }
    }

    public function getLoginStats($days = 7) {
        $stats = [
            'total_attempts' => 0,
            'successful_logins' => 0,
            'failed_attempts' => 0,
            'failed_by_ip' => [],
            'failed_by_user' => [],
            'recent_activity' => []
        ];

        if (!file_exists($this->logFile)) {
            return $stats;
        }

        $cutoffTime = strtotime("-$days days");
        $lines = file($this->logFile, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);

        foreach ($lines as $line) {
            $entry = json_decode($line, true);
            if (!$entry) continue;

            $entryTime = strtotime($entry['timestamp']);
            if ($entryTime < $cutoffTime) continue;

            $stats['total_attempts']++;

            if ($entry['status'] === 'success') {
                $stats['successful_logins']++;
            } elseif ($entry['status'] === 'failed') {
                $stats['failed_attempts']++;

                // Track failed attempts by IP
                $ip = $entry['ip_address'];
                $stats['failed_by_ip'][$ip] = isset($stats['failed_by_ip'][$ip]) ? 
                    $stats['failed_by_ip'][$ip] + 1 : 1;

                // Track failed attempts by username
                $user = $entry['username'];
                $stats['failed_by_user'][$user] = isset($stats['failed_by_user'][$user]) ? 
                    $stats['failed_by_user'][$user] + 1 : 1;
            }

            // Keep last 50 activities for recent activity
            if (count($stats['recent_activity']) < 50) {
                $stats['recent_activity'][] = $entry;
            }
        }

        return $stats;
    }

    public function searchLogs($criteria = []) {
        $results = [];

        if (!file_exists($this->logFile)) {
            return $results;
        }

        $lines = file($this->logFile, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);

        foreach ($lines as $line) {
            $entry = json_decode($line, true);
            if (!$entry) continue;

            $match = true;
            foreach ($criteria as $key => $value) {
                if (isset($entry[$key]) && stripos($entry[$key], $value) === false) {
                    $match = false;
                    break;
                }
            }

            if ($match) {
                $results[] = $entry;
            }
        }

        return array_reverse($results); // Return most recent first
    }
}

