// Quote Fetcher for Website
class QuoteFetcher {
    constructor(apiKey) {
        this.apiKey = apiKey;
        this.apiUrl = 'your-database-api-endpoint'; // Replace with your actual API endpoint
    }

    // Fetch a random quote from the database
    async fetchRandomQuote() {
        try {
            const response = await fetch(this.apiUrl, {
                method: 'GET',
                headers: {
                    'Authorization': `Bearer ${this.apiKey}`,
                    'Content-Type': 'application/json'
                }
            });

            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }

            const data = await response.json();
            return data;

        } catch (error) {
            console.error('Error fetching quote:', error);
            return this.getFallbackQuote();
        }
    }

    // Fallback quotes in case API fails
    getFallbackQuote() {
        const fallbackQuotes = [
            "The best way to predict the future is to create it. - Peter Drucker",
            "Innovation distinguishes between a leader and a follower. - Steve Jobs",
            "The only way to do great work is to love what you do. - Steve Jobs"
        ];

        const randomIndex = Math.floor(Math.random() * fallbackQuotes.length);
        return { quote: fallbackQuotes[randomIndex] };
    }

    // Display quote on the webpage
    async displayQuote() {
        const quoteData = await this.fetchRandomQuote();
        const quoteElement = document.getElementById('quote-display');

        if (quoteElement) {
            quoteElement.innerHTML = `
                <div class="quote-container">
                    <p class="quote-text">"${quoteData.quote}"</p>
                    ${quoteData.author ? `<p class="quote-author">- ${quoteData.author}</p>` : ''}
                </div>
            `;
        }
    }
}

