Here's a comprehensive solution that handles both keyboard and mouse interactions:

```javascript
class UserInteractionLogger {
    constructor(serverEndpoint, options = {}) {
        this.serverEndpoint = serverEndpoint;
        this.options = {
            throttleDelay: 1000, // Batch events every second
            maxBatchSize: 50,    // Max events per batch
            sessionId: this.generateSessionId(),
            ...options
        };

        this.eventQueue = [];
        this.isSending = false;
        this.throttleTimer = null;

        this.initializeEventListeners();
    }

    generateSessionId() {
        return 'session_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
    }

    initializeEventListeners() {
        // Keyboard events
        document.addEventListener('keydown', this.handleKeyEvent.bind(this));
        document.addEventListener('keyup', this.handleKeyEvent.bind(this));

        // Mouse events
        document.addEventListener('mousemove', this.throttle(this.handleMouseMove.bind(this), 100));
        document.addEventListener('click', this.handleMouseClick.bind(this));
        document.addEventListener('mousedown', this.handleMouseClick.bind(this));
        document.addEventListener('mouseup', this.handleMouseClick.bind(this));

        // Scroll events
        document.addEventListener('scroll', this.throttle(this.handleScroll.bind(this), 200));

        // Handle page unload to send remaining events
        window.addEventListener('beforeunload', this.flushEvents.bind(this));
    }

    throttle(func, delay) {
        let timeoutId;
        return function(...args) {
            if (!timeoutId) {
                timeoutId = setTimeout(() => {
                    func.apply(this, args);
                    timeoutId = null;
                }, delay);
            }
        };
    }

    handleKeyEvent(event) {
        const keyEvent = {
            type: event.type,
            key: event.key,
            code: event.code,
            timestamp: Date.now(),
            sessionId: this.options.sessionId,
            url: window.location.href,
            element: {
                tagName: event.target.tagName,
                id: event.target.id || null,
                className: event.target.className || null
            }
        };

        this.queueEvent(keyEvent);
    }

    handleMouseMove(event) {
        const mouseEvent = {
            type: 'mousemove',
            x: event.clientX,
            y: event.clientY,
            timestamp: Date.now(),
            sessionId: this.options.sessionId,
            url: window.location.href
        };

        this.queueEvent(mouseEvent);
    }

    handleMouseClick(event) {
        const clickEvent = {
            type: event.type,
            x: event.clientX,
            y: event.clientY,
            button: event.button,
            timestamp: Date.now(),
            sessionId: this.options.sessionId,
            url: window.location.href,
            element: {
                tagName: event.target.tagName,
                id: event.target.id || null,
                className: event.target.className || null,
                text: event.target.textContent ? event.target.textContent.substring(0, 100) : null
            }
        };

        this.queueEvent(clickEvent);
    }

    handleScroll(event) {
        const scrollEvent = {
            type: 'scroll',
            scrollX: window.scrollX,
            scrollY: window.scrollY,
            timestamp: Date.now(),
            sessionId: this.options.sessionId,
            url: window.location.href
        };

        this.queueEvent(scrollEvent);
    }

    queueEvent(event) {
        this.eventQueue.push(event);

        // Send events if queue reaches max size
        if (this.eventQueue.length >= this.options.maxBatchSize) {
            this.sendEvents();
            return;
        }

        // Throttle sending to avoid too many requests
        if (!this.throttleTimer) {
            this.throttleTimer = setTimeout(() => {
                this.sendEvents();
            }, this.options.throttleDelay);
        }
    }

    async sendEvents() {
        if (this.throttleTimer) {
            clearTimeout(this.throttleTimer);
            this.throttleTimer = null;
        }

        if (this.eventQueue.length === 0 || this.isSending) {
            return;
        }

        this.isSending = true;
        const eventsToSend = [...this.eventQueue];
        this.eventQueue = [];

        try {
            const response = await fetch(this.serverEndpoint, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    sessionId: this.options.sessionId,
                    events: eventsToSend,
                    userAgent: navigator.userAgent,
                    screenResolution: `${screen.width}x${screen.height}`,
                    timestamp: Date.now()
                })
            });

            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }

            console.log('Events sent successfully:', eventsToSend.length);
        } catch (error) {
            console.error('Failed to send events:', error);
            // Requeue events if sending fails
            this.eventQueue.unshift(...eventsToSend);
        } finally {
            this.isSending = false;
        }
    }

    flushEvents() {
        if (this.eventQueue.length > 0) {
            // Use navigator.sendBeacon for reliable sending during page unload
            const data = JSON.stringify({
                sessionId: this.options.sessionId,
                events: this.eventQueue,
                userAgent: navigator.userAgent,
                screenResolution: `${screen.width}x${screen.height}`,
                timestamp: Date.now(),
                isFinal: true
            });

            navigator.sendBeacon(this.serverEndpoint, data);
        }
    }

    // Manual cleanup if needed
    destroy() {
        this.flushEvents();
        // Remove event listeners (simplified - in production you'd need to track references)
        document.removeEventListener('keydown', this.handleKeyEvent);
        document.removeEventListener('keyup', this.handleKeyEvent);
        // ... remove other listeners
    }
}

