```javascript
// User Interaction Tracker
class UserInteractionTracker {
    constructor(options = {}) {
        this.options = {
            trackClicks: true,
            trackForms: true,
            trackScroll: true,
            trackKeypress: false,
            trackFocus: true,
            sessionId: this.generateSessionId(),
            ...options
        };

        this.interactions = [];
        this.startTime = Date.now();

        this.init();
    }

    generateSessionId() {
        return 'session_' + Math.random().toString(36).substr(2, 9) + '_' + Date.now();
    }

    init() {
        if (this.options.trackClicks) {
            this.trackClicks();
        }

        if (this.options.trackForms) {
            this.trackForms();
        }

        if (this.options.trackScroll) {
            this.trackScroll();
        }

        if (this.options.trackKeypress) {
            this.trackKeypress();
        }

        if (this.options.trackFocus) {
            this.trackFocus();
        }

        // Track page visibility changes
        this.trackVisibility();
    }

    trackClicks() {
        document.addEventListener('click', (event) => {
            const interaction = {
                type: 'click',
                target: event.target.tagName.toLowerCase(),
                className: event.target.className,
                id: event.target.id,
                text: event.target.textContent?.substring(0, 100),
                timestamp: Date.now(),
                sessionId: this.options.sessionId,
                url: window.location.href
            };

            this.logInteraction(interaction);
        }, true);
    }

    trackForms() {
        document.addEventListener('submit', (event) => {
            const form = event.target;
            const interaction = {
                type: 'form_submit',
                formId: form.id,
                formClass: form.className,
                fields: this.getFormFields(form),
                timestamp: Date.now(),
                sessionId: this.options.sessionId,
                url: window.location.href
            };

            this.logInteraction(interaction);
        });

        // Track form field changes
        document.addEventListener('change', (event) => {
            if (['input', 'select', 'textarea'].includes(event.target.tagName.toLowerCase())) {
                const interaction = {
                    type: 'form_change',
                    fieldType: event.target.type,
                    fieldName: event.target.name,
                    fieldValue: event.target.value?.substring(0, 50), // Limit value length
                    timestamp: Date.now(),
                    sessionId: this.options.sessionId,
                    url: window.location.href
                };

                this.logInteraction(interaction);
            }
        });
    }

    trackScroll() {
        let scrollTimeout;
        let lastScrollY = window.scrollY;

        window.addEventListener('scroll', () => {
            clearTimeout(scrollTimeout);
            scrollTimeout = setTimeout(() => {
                const interaction = {
                    type: 'scroll',
                    scrollY: window.scrollY,
                    scrollX: window.scrollX,
                    viewportHeight: window.innerHeight,
                    documentHeight: document.documentElement.scrollHeight,
                    timestamp: Date.now(),
                    sessionId: this.options.sessionId,
                    url: window.location.href
                };

                this.logInteraction(interaction);
                lastScrollY = window.scrollY;
            }, 100);
        });
    }

    trackKeypress() {
        document.addEventListener('keydown', (event) => {
            const interaction = {
                type: 'keypress',
                key: event.key,
                code: event.code,
                target: event.target.tagName.toLowerCase(),
                timestamp: Date.now(),
                sessionId: this.options.sessionId,
                url: window.location.href
            };

            this.logInteraction(interaction);
        });
    }

    trackFocus() {
        document.addEventListener('focusin', (event) => {
            const interaction = {
                type: 'focus',
                target: event.target.tagName.toLowerCase(),
                timestamp: Date.now(),
                sessionId: this.options.sessionId,
                url: window.location.href
            };

            this.logInteraction(interaction);
        });

        document.addEventListener('focusout', (event) => {
            const interaction = {
                type: 'blur',
                target: event.target.tagName.toLowerCase(),
                timestamp: Date.now(),
                sessionId: this.options.sessionId,
                url: window.location.href
            };

            this.logInteraction(interaction);
        });
    }

    trackVisibility() {
        document.addEventListener('visibilitychange', () => {
            const interaction = {
                type: 'visibility_change',
                state: document.visibilityState,
                timestamp: Date.now(),
                sessionId: this.options.sessionId,
                url: window.location.href
            };

            this.logInteraction(interaction);
        });
    }

    getFormFields(form) {
        const fields = {};
        const elements = form.elements;

        for (let element of elements) {
            if (element.name && !element.disabled) {
                fields[element.name] = {
                    type: element.type,
                    value: element.value?.substring(0, 50)
                };
            }
        }

        return fields;
    }

    logInteraction(interaction) {
        this.interactions.push(interaction);

        // Send to analytics endpoint (optional)
        this.sendToAnalytics(interaction);

        // Log to console for debugging (optional)
        if (this.options.debug) {
            console.log('User Interaction:', interaction);
        }
    }

    sendToAnalytics(interaction) {
        // Example: Send data to your analytics endpoint
        if (this.options.analyticsEndpoint) {
            fetch(this.options.analyticsEndpoint, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(interaction)
            }).catch(error => {
                console.warn('Failed to send analytics:', error);
            });
        }
    }

    // Get all tracked interactions
    getInteractions() {
        return this.interactions;
    }

    // Get interactions by type
    getInteractionsByType(type) {
        return this.interactions.filter(interaction => interaction.type === type);
    }

    // Clear interactions (useful for testing)
    clearInteractions() {
        this.interactions = [];
    }
}

// Usage Example:
