```javascript
class UserActivityTracker {
    constructor(analyticsEndpoint, userId = null) {
        // Endpoint of your analytics server
        this.analyticsEndpoint = analyticsEndpoint;
        // A user identifier (should be anonymized if possible)
        this.userId = userId;
        // Buffer to hold activity events before sending
        this.activityBuffer = [];
        // Maximum buffer size before sending
        this.bufferLimit = 10;
        // Debounce timer for sending data
        this.sendTimer = null;
        // Flag to check if tracking is active
        this.isTracking = false;
    }

    // Start tracking user activity
    startTracking() {
        if (this.isTracking) {
            console.warn('User activity tracking is already active.');
            return;
        }

        this.isTracking = true;

        // Track click events
        document.addEventListener('click', this.handleClick.bind(this));

        // Track keydown events (be careful with sensitive input fields)
        document.addEventListener('keydown', this.handleKeydown.bind(this));

        // Send any remaining data when the page is about to unload
        window.addEventListener('beforeunload', this.sendDataImmediately.bind(this));

        console.log('User activity tracking started.');
    }

    // Stop tracking user activity
    stopTracking() {
        if (!this.isTracking) {
            console.warn('User activity tracking is not active.');
            return;
        }

        this.isTracking = false;

        // Remove event listeners
        document.removeEventListener('click', this.handleClick.bind(this));
        document.removeEventListener('keydown', this.handleKeydown.bind(this));
        window.removeEventListener('beforeunload', this.sendDataImmediately.bind(this));

        // Send any buffered data before stopping
        this.sendDataImmediately();

        console.log('User activity tracking stopped.');
    }

    // Handle click events
    handleClick(event) {
        // Avoid tracking clicks on sensitive elements (adjust as needed)
        if (event.target.matches('input[type="password"], input[type="email"]')) {
            return;
        }

        const activity = {
            type: 'click',
            target: event.target.tagName,
            id: event.target.id || null,
            className: event.target.className || null,
            innerText: event.target.innerText ? event.target.innerText.substring(0, 50) : null, // Limit text length
            timestamp: new Date().toISOString(),
            userId: this.userId,
            url: window.location.href
        };

        this.bufferActivity(activity);
    }

    // Handle keydown events
    handleKeydown(event) {
        // Avoid tracking keystrokes in sensitive input fields
        if (event.target.matches('input[type="password"], input[type="email"], textarea')) {
            return;
        }

        const activity = {
            type: 'keydown',
            key: event.key,
            code: event.code,
            target: event.target.tagName,
            id: event.target.id || null,
            timestamp: new Date().toISOString(),
            userId: this.userId,
            url: window.location.href
        };

        this.bufferActivity(activity);
    }

    // Add activity to buffer and check if it's time to send
    bufferActivity(activity) {
        this.activityBuffer.push(activity);

        // If buffer reaches limit, send data immediately
        if (this.activityBuffer.length >= this.bufferLimit) {
            this.sendDataImmediately();
            return;
        }

        // Debounce sending to avoid too many requests
        if (this.sendTimer) {
            clearTimeout(this.sendTimer);
        }

        this.sendTimer = setTimeout(() => {
            this.sendDataImmediately();
        }, 2000); // Send after 2 seconds of inactivity
    }

    // Send data immediately to the analytics server
    sendDataImmediately() {
        if (this.activityBuffer.length === 0) {
            return;
        }

        // Create a copy of the buffer and clear it
        const dataToSend = [...this.activityBuffer];
        this.activityBuffer = [];

        // Using the Fetch API to send data
        fetch(this.analyticsEndpoint, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                activities: dataToSend,
                sentAt: new Date().toISOString()
            }),
            keepalive: true // Ensures the request completes even if page is unloading
        })
        .then(response => {
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            console.log(`Successfully sent ${dataToSend.length} activity events.`);
        })
        .catch(error => {
            console.error('Error sending activity data:', error);
            // Optionally, you could re-buffer the data to retry later
            // this.activityBuffer = [...dataToSend, ...this.activityBuffer];
        });
    }
}

